:root{--orange:#e87524;--ink:#262626;--muted:#667078;--light:#f2f4f5;--line:#dce0e2;--wp--style--global--content-size:1180px;--wp--style--global--wide-size:1380px}*{box-sizing:border-box}body{margin:0;background:white;color:var(--ink);font-family:Arial,Helvetica,sans-serif;line-height:1.6}h1,h2,h3{line-height:1.1;letter-spacing:-.025em}h1{font-size:clamp(42px,5vw,76px);max-width:820px}h2{font-size:clamp(30px,3vw,44px);font-weight:500}h3{font-size:24px;font-weight:500}p{color:#555;margin:0 0 1.4em}a{color:inherit}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--orange);outline-offset:4px}.demo-topbar{background:#292929;color:white;font-size:12px;padding:9px 4vw;display:flex;justify-content:space-between;letter-spacing:.1em}.demo-topbar span{opacity:.8}.demo-header{display:flex;align-items:center;justify-content:space-between;padding:22px 4vw;border-bottom:1px solid var(--line);background:white;gap:25px}.demo-header img{width:170px;height:auto}.demo-header nav{display:flex;gap:30px;flex-wrap:wrap}.demo-header a{text-decoration:none;font-size:14px}.demo-header .demo-enquire{border:1px solid var(--orange);padding:9px 20px}main>.wp-block-group{max-width:1180px;margin:80px auto;padding:0 24px}main>.wp-block-cover{margin:0!important}.wp-block-cover.demo-hero{padding:6vw;min-height:650px}.demo-hero p{color:white}.demo-hero .wp-block-cover__inner-container{max-width:1180px;margin:auto!important;width:100%}.wp-block-button__link{border-radius:0;background:var(--orange);color:white;padding:12px 22px;font-size:14px;font-weight:600;text-decoration:none;border:1px solid var(--orange)}.is-style-outline .wp-block-button__link{background:transparent;color:var(--ink);border:1px solid var(--line)}.wp-block-cover .wp-block-button__link{background:var(--orange);color:white}.wp-block-columns{gap:28px}.demo-card{height:100%;background:var(--light);padding:0 0 26px!important}.demo-card>h3,.demo-card>p,.demo-card>.wp-block-buttons{padding:0 22px}.demo-card figure{margin:0 0 26px}.demo-card img{width:100%;aspect-ratio:4/3;object-fit:cover}.wp-block-media-text{gap:40px}.wp-block-media-text__content{padding:0!important}.wp-block-media-text img{width:100%;object-fit:cover}.wp-block-gallery{gap:12px!important}.wp-block-gallery img{aspect-ratio:4/3;object-fit:cover}.wp-block-table{overflow-x:auto}.wp-block-table table{border-collapse:collapse;width:100%;font-size:15px}.wp-block-table th,.wp-block-table td{border:0;border-bottom:1px solid var(--line);padding:12px}.wp-block-table th{text-align:left;background:var(--light)}.wp-block-accordion-heading{font-size:21px;border-bottom:1px solid var(--line);margin:0}.wp-block-accordion-heading__toggle{padding:20px 0!important;background:transparent!important;color:var(--ink)!important}.wp-block-accordion-panel{padding:24px 0}.wp-block-file{padding:16px 0;border-bottom:1px solid var(--line)}.wp-block-file__button{background:var(--ink);border-radius:0}.stat-number{font-size:70px;line-height:1;margin:20px 0;color:var(--ink)}.demo-logos{justify-content:space-between;gap:30px}.demo-logos figure{width:150px;margin:0}.demo-logos img{width:150px;height:90px;object-fit:contain}.demo-query .wp-block-post-template{gap:28px}.demo-query .wp-block-post{background:var(--light);padding-bottom:24px}.demo-query h3,.demo-query .wp-block-post-excerpt,.demo-query .wp-block-read-more{margin-left:22px;margin-right:22px}.demo-query h3 a{text-decoration:none}.wp-block-post-featured-image img{object-fit:cover!important;width:100%;aspect-ratio:4/3}.showcase-section{border-top:1px solid var(--line);padding-top:40px!important}.showcase-section>p:first-child{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:var(--orange)}.showcase-section .demo-hero{min-height:500px!important}.showcase-section .demo-hero h1{font-size:48px}.demo-form{max-width:800px;display:grid;grid-template-columns:1fr 1fr;gap:22px}.demo-form label{font-size:14px}.demo-form input,.demo-form select,.demo-form textarea{display:block;width:100%;font:inherit;padding:12px;margin-top:6px;border:1px solid #a7afb4;background:white}.demo-form .full{grid-column:1/-1}.demo-form button{background:var(--orange);border:0;color:white;padding:14px 24px;font-weight:600;cursor:pointer}.demo-form [role=status]{padding:14px;background:#eef6ee;color:#315431}.demo-modal-content{display:none}.demo-dialog{max-width:620px;padding:36px;border:0;box-shadow:0 16px 80px #0005}.demo-dialog::backdrop{background:#0009}.demo-dialog .demo-modal-content{display:block}.demo-footer{background:var(--ink);color:white;padding:54px 4vw}.demo-footer p{color:#ddd;font-size:14px}.demo-footer strong{display:block;font-size:26px;margin-bottom:12px}.demo-footer .small{font-size:12px;color:#aaa;margin-top:35px}video{width:100%;max-height:620px;background:#202020}.wp-block-post-content{max-width:1180px;margin:auto;padding:40px 24px}.editor-styles-wrapper{font-family:Arial,Helvetica,sans-serif!important}
@media(max-width:780px){.demo-header{align-items:flex-start;flex-direction:column}.demo-header nav{gap:16px}.wp-block-cover.demo-hero{min-height:550px;padding:35px 24px}.wp-block-columns{display:block}.wp-block-column{margin-bottom:28px}.wp-block-media-text{grid-template-columns:1fr!important}.wp-block-media-text__media,.wp-block-media-text__content{grid-column:1!important;grid-row:auto!important}.wp-block-media-text__content{padding:24px 0!important}.wp-block-post-template{grid-template-columns:1fr!important}.demo-form{grid-template-columns:1fr}.demo-form label{grid-column:1}.demo-topbar span{display:none}main>.wp-block-group{margin:48px auto}.demo-logos{justify-content:flex-start}.wp-block-table{font-size:13px}.showcase-section .demo-hero h1{font-size:38px}}
